with open(r'C:\Users\nipon\Documents\opencode\idiom-master\scratch\ox_mnemonics\batch_017.json', 'r', encoding='utf-8') as f:
    batch = json.load(f)

batch_lemmas = [item['lemma'] for item in batch]

assert len(mnemonics) == len(batch_lemmas), f"Expected {len(batch_lemmas)}, got {len(mnemonics)}"
for lemma in batch_lemmas:
    assert lemma in mnemonics, f"Missing lemma: {lemma}"
    text = mnemonics[lemma]
    assert f"({lemma})" in text, f"Missing '({lemma})' in: {text}"
    assert "เชื่อมคำว่า" not in text, f"Forbidden phrase in {lemma}"
    assert "จำ" not in text or "จำจากประโยค" not in text, f"Forbidden phrase in {lemma}"

target_path = r'C:\Users\nipon\Documents\opencode\idiom-master\scratch\ox_mnemonics_done\batch_017_done.json'
with open(target_path, 'w', encoding='utf-8') as f:
    json.dump(mnemonics, f, ensure_ascii=False, indent=2)

print(f"Successfully validated and written {len(mnemonics)} mnemonics to {target_path}")
